function plot_mean_median_net_wealth_per_unit_annual
% Compare annual cross-sectional means and medians from current-unit tables.
% Source tables are regenerated by inspect_wealth_distributions.
scriptDir=fileparts(mfilename('fullpath'));
outDir=fullfile(scriptDir,'figures');
t=readtable(fullfile(outDir,'wealth_distribution_annual.csv'),'TextType','string');
b=sortrows(t(t.scenario=="benchmark",:),'year');
n=sortrows(t(t.scenario=="counterfactual_no_ageing",:),'year');
assert(isequal(b.year,n.year) && b.year(1)==2025 && b.year(end)==2070);
assert(abs(b.mean(1)-n.mean(1))<1e-8 && abs(b.p50(1)-n.p50(1))<1e-8);
blue=[0.13 0.42 0.66]; orange=[0.83 0.31 0.06]; dark=[0.12 0.15 0.18];
fig=figure('Visible','off','Color','white','Position',[80 80 2000 820]);
layout=tiledlayout(fig,1,2,'Padding','compact','TileSpacing','compact');
fields=["mean","p50"]; headings=["Mean net wealth per benefit unit","Median net wealth per benefit unit"];
for k=1:2
    ax=nexttile(layout); hold(ax,'on');
    bv=b.(fields(k))/1000; nv=n.(fields(k))/1000;
    plot(ax,b.year,bv,'Color',blue,'LineWidth',3.5,'DisplayName','Baseline');
    plot(ax,n.year,nv,'Color',orange,'LineWidth',3.5,'DisplayName','No ageing');
    plot(ax,2070,bv(end),'o','MarkerSize',7,'MarkerFaceColor',blue,'MarkerEdgeColor',blue,'HandleVisibility','off');
    plot(ax,2070,nv(end),'o','MarkerSize',7,'MarkerFaceColor',orange,'MarkerEdgeColor',orange,'HandleVisibility','off');
    % Direct labels outside the trajectories, spaced by at least 6% of scale.
    span=max([bv;nv])-min([bv;nv]);
    positions=[bv(end),nv(end)];
    if abs(diff(positions))<0.065*span
        midpoint=mean(positions);
        if positions(1)<positions(2), positions=midpoint+[-1,1]*0.0325*span;
        else, positions=midpoint+[1,-1]*0.0325*span; end
    end
    text(ax,2070.8,positions(1),sprintf('%.0f',bv(end)),'Color',blue,'FontSize',18,'FontWeight','bold','VerticalAlignment','middle');
    text(ax,2070.8,positions(2),sprintf('%.0f',nv(end)),'Color',orange,'FontSize',18,'FontWeight','bold','VerticalAlignment','middle');
    set(ax,'Color','white','XLim',[2025,2075],'XTick',[2025,2035,2045,2055,2070],...
        'YLim',[0,1.12*max([bv;nv])],'FontSize',17,'Box','off','TickDir','out',...
        'XColor',dark,'YColor',dark,'GridColor',[0.75,0.77,0.8],'GridAlpha',0.18);
    ax.YGrid='on'; ax.XGrid='off';
    xlabel(ax,'Simulation year','FontSize',18);
    title(ax,[headings(k);"(thousand pounds, 2015 prices)"],'FontSize',20,'Color',dark);
    legend(ax,'Location','northwest','Box','off','FontSize',18,'TextColor',dark,'Color','white');
end
exportgraphics(fig,fullfile(outDir,'mean_median_net_wealth_per_unit_annual.png'),'Resolution',220);
exportgraphics(fig,fullfile(outDir,'mean_median_net_wealth_per_unit_annual.pdf'),'ContentType','vector');
close(fig);
end
